// Rust core shortcut event listener pseudo
fn handle_shortcut_event(event: ShortcutEvent) {
    if event.is_pressed() {
        audio_recorder.start();
    } else {
        let audio = audio_recorder.stop();
        let text = whisper_engine.transcribe(audio);
        active_window.paste(text);
    }
}

